// The Better Auth CLI writes `timestamp("x")`, which is timestamp without
// time zone. Every timestamp in this codebase is timestamptz, so this runs
// after every generate and rewrites them. Idempotent.
import { readFileSync, writeFileSync } from "node:fs";

const file = "src/lib/db/auth-schema.ts";
const header = `// Generated by the Better Auth CLI from src/lib/auth/server.ts, then passed
// through scripts/fix-auth-schema.mjs so every timestamp is timestamptz.
// Do not edit by hand. Run \`pnpm auth:generate\` after changing the auth
// config or its plugins.

`;

const before = readFileSync(file, "utf8");
let after = before.replace(/timestamp\("([a-z_]+)"\)/g, 'timestamp("$1", { withTimezone: true })');
if (!after.startsWith("// Generated by the Better Auth CLI")) after = header + after;
if (after !== before) writeFileSync(file, after);

const remaining = (after.match(/timestamp\("[a-z_]+"\)/g) ?? []).length;
console.log(remaining === 0 ? `fix-auth-schema: every timestamp in ${file} is timestamptz.` : `fix-auth-schema: ${remaining} timestamps still lack a time zone.`);
process.exit(remaining === 0 ? 0 : 1);
